 if(q){let cached=searchCache.get(n);if(!cached||cached.labelKey!==labelKey){cached={labelKey,text:normalizedSearch([n.title,n.body,...n.items.map(i=>i.text),...n.labels.map(id=>labelNames.get(id)||'')].join(' '))};searchCache.set(n,cached);}if(!cached.text.includes(q))return false;}
 if(skipType)return true;
