function renderEditorLabels(){if(!editing)return;$('editor-labels').innerHTML=(editing.reminderAt?`<button class="label-chip" id="edit-reminder-chip">${icon('clock')}${esc(new Date(editing.reminderAt).toLocaleString('es-AR'))}</button>`:'')+editing.labels.map(id=>labels.find(l=>l.id===id)).filter(Boolean).map(l=>`<button class="label-chip" data-editor-label="${esc(l.id)}" title="Etiqueta">${esc(l.name)}</button>`).join('');if($('edit-reminder-chip'))$('edit-reminder-chip').onclick=()=>reminderDialog(editing.id);}
