 try{await saveDraft();if(!hasContent(editing))await store.deleteNote(editing.id);}catch(e){cancelMotion($('editor'));cancelMotion($('editor-layer'));showError(e);return false;}
 for(const audio of $('editor-audios').querySelectorAll('audio'))audio.pause?.();
 try{await refresh();}catch(e){cancelMotion($('editor'));cancelMotion($('editor-layer'));showError(e);return false;}
 const target=noteElement($('notes-area'),editorReturnId);hidePopover();
 await closingMotion;
 $('editor-audios').replaceChildren();editing=null;checklistKey=null;editorRender++;$('editor-layer').hidden=true;document.body.classList.remove('editor-open');document.body.style.top='';if(editorScroll)globalThis.scrollTo?.({left:editorScroll.x,top:editorScroll.y,behavior:'instant'});editorScroll=null;cancelMotion($('editor'));cancelMotion($('editor-layer'));setEditorBackground(false);
