function setEditorBackground(inert){for(const element of document.querySelectorAll('.header,.sidebar,main,.mobile-bar,.drive-bar,.update-bar'))element.inert=inert;}

async function mutateNote(id,changes,{undoLabel}={}){const n=editing?.id===id?editing:clone(notes.find(n=>n.id===id));if(!n)return;const old=clone(n);Object.assign(n,changes,{updatedAt:now()});if(settings.updatedFirst!==false&&contentSignature(n)!==contentSignature(old))n.order=nextOrder();if(editing?.id===id){await saveDraft();renderEditor();}else await store.putNote(n);await refresh();if(undoLabel)toast(undoLabel,'Deshacer',async()=>{await store.putNote(old);if(editing?.id===id){editing=clone(old);renderEditor();}await refresh();});}
async function trashNote(id){await mutateNote(id,{deletedAt:now()},{undoLabel:'Nota enviada a la papelera'});if(editing?.id===id)await closeEditor();selected.delete(id);}
async function archiveNote(id){const n=editing?.id===id?editing:notes.find(n=>n.id===id);if(!n)return;await mutateNote(id,{archived:!n.archived},{undoLabel:n.archived?'Nota desarchivada':'Nota archivada'});if(editing?.id===id)await closeEditor();selected.delete(id);}
function showPopover(anchor,html){hidePopover();popoverTarget=anchor;$('popover').innerHTML=html;$('popover').hidden=false;const r=anchor.getBoundingClientRect(),p=$('popover');const w=p.offsetWidth,h=p.offsetHeight;p.style.left=`${Math.max(8,Math.min(r.left,innerWidth-w-8))}px`;const top=r.bottom+6;p.style.top=`${Math.max(8,top+h>innerHeight?r.top-h-6:top)}px`;animateSurface(p);}
function hidePopover(){$('popover').hidden=true;popoverTarget=null;}
function menuItem(action,label,i){return `<button class="menu-action" data-menu="${action}">${icon(i)}<span>${esc(label)}</span></button>`;}
function colorPopover(anchor,id){const n=editing?.id===id?editing:notes.find(n=>n.id===id);showPopover(anchor,`<div class="popover-heading">Color de la nota</div><div class="color-picker" role="radiogroup" aria-label="Color">${palette.map(p=>`<button class="color-swatch" role="radio" aria-checked="${n.color===p[0]}" aria-label="${p[1]}" title="${p[1]}" data-color="${p[0]}" style="background:${p[document.body.classList.contains('dark')?3:2]||'var(--surface)'}">${n.color===p[0]?icon('check'):''}</button>`).join('')}</div><hr><div class="popover-heading">Fondo</div><div class="background-picker">${[['none','Sin fondo','∅'],['paper','Papel','☰'],['dots','Puntos','⠿'],['music','Música','♫']].map(([v,l,g])=>`<button class="background-choice ${n.background===v?'active':''}" data-background="${v}" aria-label="${l}">${g}</button>`).join('')}</div>`);$('popover').onclick=async e=>{const c=e.target.closest('[data-color]'),b=e.target.closest('[data-background]');if(c||b){try{await mutateNote(id,c?{color:c.dataset.color}:{background:b.dataset.background});colorPopover(anchor,id);}catch(err){showError(err);}}};}
function labelPopover(anchor,id){const n=editing?.id===id?editing:notes.find(n=>n.id===id);showPopover(anchor,`<div class="popover-heading">Etiquetar nota</div><input class="popover-input" id="label-search" placeholder="Ingresar nombre de etiqueta" aria-label="Buscar o crear etiqueta"><div id="label-options">${labels.map(l=>`<label class="label-option"><input type="checkbox" data-label-choice="${esc(l.id)}" ${n.labels.includes(l.id)?'checked':''}>${esc(l.name)}</label>`).join('')}</div><button class="menu-action" id="create-label-here">${icon('plus')}Crear etiqueta</button>`);$('popover').onchange=async e=>{const v=e.target.dataset.labelChoice;if(v){try{const current=editing?.id===id?editing:notes.find(n=>n.id===id);await mutateNote(id,{labels:e.target.checked?[...new Set([...current.labels,v])]:current.labels.filter(x=>x!==v)});}catch(err){showError(err);}}};$('label-search').oninput=e=>{for(const row of $('label-options').children)row.hidden=!row.textContent.toLowerCase().includes(e.target.value.toLowerCase());};$('create-label-here').onclick=async()=>{const name=$('label-search').value.trim();if(!name){$('label-search').focus();return;}try{let l=labels.find(l=>l.name.toLocaleLowerCase()===name.toLocaleLowerCase());if(!l){l={id:uid(),name};await store.putLabel(l);labels.push(l);}await mutateNote(id,{labels:[...new Set([...n.labels,l.id])]});labelPopover(anchor,id);}catch(err){showError(err);}};}
function morePopover(anchor,id){const n=editing?.id===id?editing:notes.find(n=>n.id===id);showPopover(anchor,menuItem('trash','Eliminar nota','trash')+menuItem('label','Agregar etiqueta','label')+menuItem('copy','Crear una copia','copy')+menuItem('list',n.isList?'Ocultar casillas de verificación':'Mostrar casillas de verificación','checklist')+menuItem('drawing','Agregar dibujo','draw')+menuItem('text','Descargar texto','download'));$('popover').onclick=async e=>{const a=e.target.closest('[data-menu]')?.dataset.menu;if(!a)return;hidePopover();try{if(a==='trash')await trashNote(id);if(a==='label')labelPopover(anchor,id);if(a==='copy')await duplicateNote(id);if(a==='list')await toggleList(id);if(a==='drawing'){if(editing?.id!==id)await openEditor(id);openDrawing();}if(a==='text')downloadText(n);}catch(err){showError(err);}};}
async function toggleList(id){const n=editing?.id===id?editing:clone(notes.find(n=>n.id===id));if(!n)return;if(!n.isList){n.items=n.body.split('\n').filter(t=>t.trim()).map(text=>({id:uid(),text,checked:false}));if(!n.items.length)n.items=[{id:uid(),text:'',checked:false}];n.isList=true;}else{n.body=n.items.map(i=>i.text).join('\n');n.richBody='';n.items=[];n.isList=false;}if(editing?.id===id){$('editor-body').textContent=n.body;await saveDraft();renderEditor();}else await store.putNote(localSnapshot(n));await refresh();}
async function duplicateNote(id){if(editing?.id===id)await saveDraft();const n=clone(editing?.id===id?editing:notes.find(n=>n.id===id));if(!n)return;n.id=uid();n.createdAt=now();n.updatedAt=now();n.order=nextOrder();n.deletedAt=null;n.archived=false;const original=[...n.attachments];n.attachments=[];await store.putNote(n);try{for(const key of original){const a=await getAttachment(key);if(!a||a.draft)continue;const next={...a,id:uid(),noteId:n.id};n.attachments.push(next.id);await store.attachToNote(n,next);}}catch(e){await store.deleteNote(n.id);throw e;}await refresh();toast('Se creó una copia');}
