async function handleFiles(files,{imagesOnly=false}={}){
 if(!files.length)return;if(attachmentTask)await attachmentTask.catch(()=>{});if(!editing)await openEditor();
 const target=editing;const task=(async()=>{
  const existing=(await Promise.all(target.attachments.map(getAttachment))).filter(Boolean);
  if(imagesOnly&&files.some(f=>!attachmentType(f).startsWith('image/')))throw Error('Elegí un archivo de imagen.');
  validateFiles(files,existing);
  let added=0;try{for(const file of files){if(editing!==target)throw Error('La nota cambió. Volvé a seleccionar los archivos.');await addAttachment(file,attachmentType(file),file.name||'Archivo adjunto',{originalFile:true});added++;}}
  catch(error){if(added)error.message=`Se guardaron ${added} de ${files.length} archivos. ${error.message}`;throw error;}
 })();attachmentTask=task;
 try{await task;}finally{if(attachmentTask===task)attachmentTask=null;drive?.resume();}
}
async function startRecording(){
 if(!editing||operationBusy||stopTask||recorder&&recorder.state!=='idle')return;liveWave.prepare();operationBusy=true;try{await saveDraft();}catch(e){operationBusy=false;liveWave.release();throw e;}recordingNoteId=editing.id;recordingId=uid();recordingPauseTotal=0;recordingPausedAt=0;const target=editing;
 recorder=new AudioRecorder({onStream:stream=>{if(stream)liveWave.start(stream);else liveWave.release();},onChunk:async chunk=>{if(!editing||editing.id!==recordingNoteId)return;const a={id:uid(),noteId:recordingNoteId,blob:chunk.blob,type:chunk.mimeType||'audio/mp4',name:'Grabación en curso',createdAt:now(),draft:true,recordingId,index:chunk.index,duration:chunk.elapsed};target.attachments.push(a.id);try{await store.attachToNote(localSnapshot(target),a);attachmentCache.set(a.id,a);}catch(e){target.attachments=target.attachments.filter(x=>x!==a.id);throw e;}},onState:state=>{if(stopTask&&state==='idle')state='stopping';liveWave.setState(state);const active=state!=='idle';$('editor-mic').disabled=active;$('record-panel').hidden=!active;$('record-panel').classList.toggle('paused',state==='paused');$('record-pause').disabled=['requesting','stopping'].includes(state);$('record-stop').disabled=['requesting','stopping'].includes(state);$('record-label').textContent=state==='requesting'?'Esperando micrófono…':state==='paused'?'En pausa':state==='stopping'?'Guardando audio…':'Grabando audio';setIcon('record-pause',state==='paused'?'play':'pause');},onError:error=>{status('Error de grabación',true);showError(error);}});
 try{await recorder.start();if(recorder.state!=='recording')return;recordingStarted=performance.now();$('record-time').textContent='00:00';clearInterval(recordingTimer);recordingTimer=setInterval(()=>{if(recorder.state==='recording')$('record-time').textContent=formatTime((performance.now()-recordingStarted-recordingPauseTotal)/1000);},250);}catch(e){$('record-panel').hidden=true;$('editor-mic').disabled=false;showError(e);}finally{operationBusy=false;}
}
async function stopRecording(){if(stopTask)return stopTask;stopTask=finishRecording();try{return await stopTask;}finally{stopTask=null;$('editor-mic').disabled=recorder?.state!=='idle';if(recorder?.state==='idle')$('record-panel').hidden=true;}}
async function finishRecording(){if(!recorder||recorder.state==='idle')return;let result;try{result=await recorder.stop();}catch(e){if(e.recording)result=e.recording;else {showError(e);return false;}}clearInterval(recordingTimer);if(!result?.blob.size){toast('No se recibió audio del micrófono.');return false;}
 $('record-label').textContent='Preparando audio…';result=await prepareRecording(result,{fallbackWaveform:liveWave.waveform(result.duration),onProgress:percent=>{$('record-label').textContent=`Convirtiendo a MP3… ${percent}%`;}});
 try{const drafts=editing.attachments.filter(id=>attachmentCache.get(id)?.draft&&attachmentCache.get(id)?.recordingId===recordingId);const a={id:uid(),noteId:editing.id,blob:result.blob,type:result.mimeType||result.blob.type||'audio/mp4',name:`Audio ${new Date().toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'})}`,duration:result.duration,waveform:result.waveform,createdAt:now()};const old=[...editing.attachments];editing.attachments=editing.attachments.filter(id=>!drafts.includes(id));editing.attachments.push(a.id);try{await store.attachToNote(localSnapshot(editing),a,{deleteIds:drafts});}catch(e){editing.attachments=old;throw e;}for(const id of drafts)dropURL(id);attachmentCache.set(a.id,a);await renderEditorAttachments();$('record-panel').hidden=true;$('editor-mic').disabled=false;status('Audio guardado');if(result.conversionFailed)toast('No se pudo convertir a MP3. Se conservó la grabación original.');return true;}catch(e){showError(e);download(result.blob,`guarda-audio-recuperado.${audioExtension(result.mimeType)}`);toast('No se pudo guardar el audio. Se descargó una copia de recuperación.');return false;}}
async function recoverDraftRecordings(){let recovered=0;const drafts=await store.draftAttachments(),byNote=new Map();for(const a of drafts){if(!byNote.has(a.noteId))byNote.set(a.noteId,[]);byNote.get(a.noteId).push(a);}for(const note of notes){const groups=new Map();for(const a of byNote.get(note.id)||[]){if(note.attachments.includes(a.id)){const key=a.recordingId||'unknown';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(a);}}for(const chunks of groups.values()){chunks.sort((a,b)=>a.index-b.index);const type=chunks[0].type;const a={id:uid(),noteId:note.id,blob:new Blob(chunks.map(a=>a.blob),{type}),type,name:'Audio recuperado',createdAt:now(),duration:chunks.at(-1).duration||0};const ids=chunks.map(a=>a.id);const next={...note,attachments:[...note.attachments.filter(id=>!ids.includes(id)),a.id]};await store.attachToNote(next,a,{deleteIds:ids});Object.assign(note,next);recovered++;}}if(recovered)toast(`${recovered} ${recovered===1?'grabación recuperada':'grabaciones recuperadas'} después de una interrupción.`);}
function utility(title,body,actions=[]){hidePopover();$('utility-content').innerHTML=`<h2>${esc(title)}</h2>${body}<div class="dialog-actions">${actions.map((a,i)=>`<button class="text-button ${a.primary?'primary-button':''} ${a.danger?'destructive':''}" data-dialog-action="${i}">${esc(a.label)}</button>`).join('')}</div>`;$('utility-dialog').showModal();animateSurface($('utility-dialog'));$('utility-content').onclick=async e=>{const b=e.target.closest('[data-dialog-action]');if(!b)return;try{b.disabled=true;await actions[Number(b.dataset.dialogAction)].run?.();}catch(err){showError(err);}finally{if(b.isConnected)b.disabled=false;}};}
