function reminderDialog(id){const n=editing?.id===id?editing:notes.find(n=>n.id===id);const value=n.reminderAt?new Date(n.reminderAt-new Date(n.reminderAt).getTimezoneOffset()*60000).toISOString().slice(0,16):'';utility('Recordarme',`<div class="dialog-row"><input type="datetime-local" id="reminder-date" aria-label="Fecha y hora" value="${value}"></div><p class="small">Guarda te avisará mientras la app esté abierta. Los avisos con la app cerrada quedan para una próxima versión.</p>`,[{label:'Cancelar',run:closeUtility},...(n.reminderAt?[{label:'Quitar',run:async()=>{await mutateNote(id,{reminderAt:null,reminderNotified:false});closeUtility();}}]:[]),{label:'Guardar',primary:true,run:async()=>{const date=new Date($('reminder-date').value).getTime();if(!Number.isFinite(date))throw new Error('Elegí una fecha y hora.');await mutateNote(id,{reminderAt:date,reminderNotified:false});closeUtility();}}]);}
function editLabels(){utility('Editar etiquetas',`<div class="label-edit-row"><span>${icon('plus')}</span><input type="text" id="new-label-name" placeholder="Crear una etiqueta nueva" aria-label="Nueva etiqueta"><button class="icon-button" id="save-new-label" aria-label="Crear etiqueta">${icon('check')}</button></div><div id="labels-editor">${labels.map(l=>`<div class="label-edit-row" data-label-row="${esc(l.id)}"><button class="icon-button" data-delete-label="${esc(l.id)}" aria-label="Eliminar etiqueta">${icon('trash')}</button><input type="text" value="${esc(l.name)}" aria-label="Nombre de etiqueta"><button class="icon-button" data-save-label="${esc(l.id)}" aria-label="Guardar nombre">${icon('check')}</button></div>`).join('')}</div>`,[{label:'Listo',run:closeUtility}]);
 const add=async()=>{const name=$('new-label-name').value.trim();if(!name)return;if(labels.some(l=>l.name.toLocaleLowerCase()===name.toLocaleLowerCase()))throw new Error('Ya existe una etiqueta con ese nombre.');await store.putLabel({id:uid(),name});await refresh();closeUtility();editLabels();};$('save-new-label').onclick=()=>add().catch(showError);$('new-label-name').onkeydown=e=>{if(e.key==='Enter')add().catch(showError);};$('labels-editor').onclick=async e=>{const del=e.target.closest('[data-delete-label]'),save=e.target.closest('[data-save-label]');try{if(del){const id=del.dataset.deleteLabel;await store.deleteLabel(id);if(editing)editing.labels=editing.labels.filter(x=>x!==id);if(route===`label:${id}`)navigate('notes');}if(save){const name=save.closest('.label-edit-row').querySelector('input').value.trim();if(!name)throw new Error('La etiqueta necesita un nombre.');const id=save.dataset.saveLabel;if(labels.some(l=>l.id!==id&&l.name.toLowerCase()===name.toLowerCase()))throw new Error('Ya existe una etiqueta con ese nombre.');await store.putLabel({id,name});}if(del||save){await refresh();closeUtility();editLabels();}}catch(err){showError(err);}};
}
