async function init(){
 bindEvents();try{await store.init();settings=await loadSettings();applyTheme();[notes,labels]=await Promise.all([store.allNotes(),store.allLabels()]);const hash=decodeURIComponent(location.hash.slice(1));if(/^(notes|archive|trash|reminders)$/.test(hash)||hash.startsWith('label:'))route=hash;await recoverDraftRecordings();applySettings();await refresh();await navigator.storage?.persist?.().catch(()=>false);matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(settings.theme==='system')applyTheme();});checkReminders().catch(showError);setInterval(()=>checkReminders().catch(showError),30000);drive=initDrive({store,isBusy:cloudBusy,onApplied:async changed=>{if(changed){clearAttachments();selected.clear();await refresh();}},utility,closeUtility,showError});initProfile({store,drive,utility,closeUtility,showError});$('drive-open').onclick=()=>drive.open().catch(showError);initUpdater(APP_VERSION,{beforeReload:()=>drive?.prepareReload(),isBusy:()=>cloudBusy()||drive?.isWorking(),saveState:async()=>{await saveDraft();await saveChain;await store.whenIdle();}});}catch(error){applyThemePreference();status('Almacenamiento no disponible',true);$('empty-state').hidden=false;$('empty-icon').innerHTML=icon('info');$('empty-message').textContent='No se pudo abrir el almacenamiento de Guarda.';$('empty-create').hidden=true;showError(error);}
}
init();
